package in.sevasetu.amc.web;
import in.sevasetu.amc.security.CurrentUser;import org.springframework.jdbc.core.simple.JdbcClient;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/reports") @PreAuthorize("hasAnyRole('OWNER','ADMIN')") public class ReportController{private final JdbcClient db;public ReportController(JdbcClient db){this.db=db;}
 @GetMapping Map<String,Object> report(@AuthenticationPrincipal CurrentUser u,@RequestParam(defaultValue="MONTH")String period){CustomerController.tenant(u);var interval=switch(period){case "WEEK"->"7 days";case "TWO_WEEKS"->"14 days";case "QUARTER"->"3 months";case "TWO_QUARTERS"->"6 months";case "YEAR"->"1 year";default->"1 month";};var result=new LinkedHashMap<String,Object>();result.put("period",period);result.put("currentMonth",summary(u,"date_trunc('month',current_date)"));result.put("selected",summary(u,"current_date-interval '"+interval+"'"));result.put("salesByType",db.sql("select coalesce(ci.type,case when oi.item_kind='PACKAGE' then 'PACKAGE' else 'PRODUCT' end) sale_type,sum(oi.quantity) quantity,sum((oi.unit_price-oi.discount)*oi.quantity) revenue,count(distinct o.id) orders from amcservice.order_items oi join amcservice.orders o on o.id=oi.order_id left join amcservice.catalog_items ci on ci.id=oi.item_id and oi.item_kind='ITEM' where o.tenant_id=:t and o.created_at>=current_date-interval '"+interval+"' group by sale_type order by revenue desc").param("t",u.tenantId()).query().listOfRows());result.put("items",db.sql("select oi.description,coalesce(ci.type,case when oi.item_kind='PACKAGE' then 'PACKAGE' else 'PRODUCT' end) sale_type,sum(oi.quantity) quantity,sum((oi.unit_price-oi.discount)*oi.quantity) revenue,count(distinct o.id) orders from amcservice.order_items oi join amcservice.orders o on o.id=oi.order_id left join amcservice.catalog_items ci on ci.id=oi.item_id and oi.item_kind='ITEM' where o.tenant_id=:t and o.created_at>=current_date-interval '"+interval+"' group by oi.description,sale_type order by revenue desc,quantity desc").param("t",u.tenantId()).query().listOfRows());result.put("chefs",db.sql("select e.id,e.name,b.name branch_name,count(distinct jc.job_card_id) jobs,count(distinct case when j.status='COMPLETED' then j.id end) completed from amcservice.employees e join amcservice.branches b on b.id=e.branch_id left join amcservice.job_card_chefs jc on jc.employee_id=e.id left join amcservice.job_cards j on j.id=jc.job_card_id and j.created_at>=current_date-interval '"+interval+"' where e.tenant_id=:t and e.job_role='CHEF' group by e.id,b.name order by jobs desc,e.name").param("t",u.tenantId()).query().listOfRows());return result;}
 private Map<String,Object> summary(CurrentUser u,String start){return db.sql("select coalesce(sum(total),0) sales,count(*) orders,coalesce(sum(amount_paid),0) collected,coalesce(sum(total-amount_paid),0) outstanding from amcservice.orders where tenant_id=:t and created_at>="+start).param("t",u.tenantId()).query().listOfRows().getFirst();}
}
